node -e 'const d=require("dgram"),c=require("crypto"),s=d.createSocket("udp4"),p=[],q=(h,pt)=>s.send(Buffer.concat([Buffer.from("000100002112a442","hex"),c.randomBytes(12)]),pt,h);setTimeout(()=>{console.log("Timed out. Replies:",p);process.exit(1)},4000);s.on("message",(m,r)=>{p.push({from:r.address,port:m.readUInt16BE(26)^0x2112});if(p.length===2){console.log(p[0].port===p[1].port?"Cone NAT (Not Symmetric)":"Symmetric NAT",p);process.exit(0)}});q(["stun","cloudflare","com"].join("."),3478);q(["stun","nextcloud","com"].join("."),443)'
